D={
28:{"t":"두로의 왕과 에덴의 그룹","q":"스스로 신이라 한 통치자는 어떻게 사람임이 드러날까요?","g":["26~27장의 두로 심판에 이어, 이번에는 두로의 통치자와 왕을 향한 말씀이에요.","교만한 선언, 에덴의 애가, 시돈으로 이어지고 끝에서는 흩어진 이스라엘을 다시 모으겠다고 해요. 29장은 이집트 차례예요."],"one":"너는 사람이지 신이 아니다. 그런데도 네 마음을 하나님의 마음처럼 여겼다."},
29:{"t":"나일강의 괴물 파라오","q":"'나일강은 내 거다'라던 파라오는 어떻게 끌려 올라올까요?","g":["열째 해, 예루살렘이 포위되던 때에 말씀이 이집트와 파라오로 향해요. 이웃 나라 심판의 마지막 대상이에요.","강의 괴물, 갈대 지팡이, 마흔 해의 폐허를 지나 스물일곱째 해에 덧붙인 말씀으로 끝나요. 30장에서 이집트 이야기가 이어져요."],"one":"이집트는 다시는 이스라엘 집안이 믿고 기댈 데가 되지 못할 것이다."},
30:{"t":"여호와의 날과 꺾인 팔","q":"꺾인 파라오의 팔 대신 칼을 쥐는 팔은 누구의 팔일까요?","g":["29장에 이어 이집트에게 '여호와의 날'이 가까웠다고 외쳐요. 동맹국과 이집트 성읍들의 이름이 줄줄이 나와요.","끝은 꺾인 파라오의 팔 이야기예요. 31장은 같은 이집트를 큰 나무에 빗대요."],"one":"나는 바빌론 왕의 팔에 힘을 주고, 내 칼을 그의 손에 쥐여 주겠다."},
31:{"t":"찍혀 넘어진 백향목","q":"하나님의 동산에서도 가려지지 않던 나무는 누구였을까요?","g":["파라오에게 '너는 누구와 같으냐'고 물으며, 아시리아라는 큰 백향목이 어떻게 무너졌는지 보여 줘요.","32장에서 같은 파라오를 위한 애가가 이어져요."],"one":"에덴의 나무들 가운데, 그 영광과 위세로 보면 너는 누구와 같으냐?"},
32:{"t":"파라오를 위한 애가와 스올","q":"구덩이 속에는 먼저 내려간 누가 누워 있을까요?","g":["31장의 큰 나무 비유 다음, 파라오를 위한 애가와 죽은 자들의 땅 이야기예요. 열두째 해의 두 말씀이에요.","이집트를 향한 말씀은 여기서 끝나요. 33장에서 에스겔의 입이 열리고 새 국면이 시작돼요."],"one":"네가 누구보다 더 아름답다는 거냐? 내려가라. 할례받지 못한 자들과 함께 누워라."},
33:{"t":"파수꾼과 함락 소식","q":"예루살렘이 함락됐다는 소식은 누구를 통해 도착할까요?","g":["다시 파수꾼의 책임으로 돌아와요. 3장에서 세운 그 파수꾼 이야기가 이어져요.","도망쳐 온 사람이 예루살렘의 함락을 알리고 에스겔의 입이 열려요. 34장에서는 이스라엘의 목자들이 나와요."],"one":"내 입이 열렸고, 나는 더 이상 말 못 하는 사람이 아니었다."},
34:{"t":"자기 배만 채운 목자와 참 목자","q":"양 떼를 돌보지 않은 목자 대신 누가 양을 찾을까요?","g":["예루살렘이 무너진 뒤 첫 말씀이에요. 흩어진 양 떼와 그 목자들을 두고 하나님이 말씀하세요.","잃은 양을 찾는 하나님, 한 목자 다윗, 평화의 언약으로 이어져요. 35장은 에돔의 세일산을 향해요."],"one":"봐라, 내가, 바로 내가 내 양 떼를 찾고 돌보겠다."},
35:{"t":"세일산에게","q":"세일산은 이스라엘의 산들을 두고 뭐라고 말했을까요?","g":["34장의 목자 이야기에 이어, 이웃 에돔의 세일산을 향해 말씀하세요. 25장에서 한 번 나온 에돔이에요.","36장에서는 같은 이스라엘의 산들에게 회복을 말해요."],"one":"이스라엘 집안의 유산이 황폐해졌다고 네가 기뻐했으니, 나도 너에게 그대로 해 주겠다."},
36:{"t":"이스라엘의 산들과 새 마음","q":"하나님은 이 일을 왜 '너희 때문이 아니다'라고 하실까요?","g":["6장에서 심판을 들었던 이스라엘의 산들에게 이번에는 회복을 말해요. 35장 세일산과 짝을 이뤄요.","돌아옴과 정결, 새 마음과 새 영을 지나 에덴동산 같은 땅까지 나아가요. 37장은 마른 뼈 환상으로 이어져요."],"one":"너희에게 새 마음을 주고, 너희 속에 새 영을 넣어 주겠다. 너희 몸에서 돌 같은 마음을 없애고, 살 같은 마음을 주겠다."},
37:{"t":"마른 뼈들과 두 막대기","q":"마른 뼈에게 예언하면 어떤 일이 벌어질까요?","g":["36장의 회복 약속이 눈에 보이는 환상이 돼요. 말라 버린 뼈 골짜기에서 시작해요.","뼈 환상 뒤에는 두 막대기가 하나로 붙는 행동 예언이 따라와요. 38장에서는 북쪽의 곡이 등장해요."],"one":"내가 내 영을 너희 속에 넣겠다. 그러면 너희가 살아날 것이다."},
}
